-- Sinh tự động bởi scripts/gen_seed_sql.py — ĐỪNG SỬA TAY.
-- Nguồn: dienmayxanh_products.csv
-- 1413 sản phẩm / 62 category (= nhóm) / 5 parent / 157 brand.
--
-- File này nằm trong db/init nên postgres chạy nó một lần khi volume còn
-- trống; sửa CSV thì chạy lại `python3 scripts/gen_seed_sql.py` rồi xoá
-- volume để nạp lại. Idempotent: TRUNCATE trước khi insert.

BEGIN;

TRUNCATE mwg.product, mwg.brand, mwg.categories RESTART IDENTITY CASCADE;

-- categories: 62 nhóm, category_name = group_name, parent = 5 mục lớn

-- brand: 157 hãng, brand_id tường minh 1..N
SELECT setval(pg_get_serial_sequence('mwg.brand', 'brand_id'), (SELECT max(brand_id) FROM mwg.brand));

-- product

COMMIT;
